powerpagecomponent.content:
{
  "source": "{% include 'Compliance Settings' %}
{% include 'Default Portal' %}
{% if request.params['contactid']%}
{% assign contactid = request.params['contactid'] %}
{% assign contact = entities['contact'][contactid] %}
{% endif %}

{% if request.params['registrationid'] %}
{% assign registrationid = request.params['registrationid'] %}
{% assign new_candidateregistration = entities['new_candidateregistration'][registrationid] %}
{% assign compliancetypeid = new_candidateregistration.new_compliancetypeid.id %}

{% else %}
{% endif %}
{% block title %}{% endblock %}

<html>

<head>
    <!-- font awesome connection -->
    <link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.7.2/css/all.min.css">

    <style>
        .progress-container {
            display: flex;
            justify-content: space-between;
            align-items: center;
            background: #e1dadc;
            padding: 10px;
            border-radius: 8px;
            margin-bottom: 20px;
        }

        .steps-wrapper {
            display: flex;
            flex: 1;
            justify-content: space-between;
        }

        .step {
            text-align: center;
            flex: 1;
            position: relative;
        }

        .step:not(:last-child)::after {
            content: '';
            position: absolute;
            top: 12px;
            left: 50%;
            right: -50%;
            height: 4px;
            background: #d3e4ec;
            z-index: -1;
        }

        .step.active:not(:last-child)::after {
            background: #28a745;
        }

        .circle {
            width: 24px;
            height: 24px;
            background: #8e8e80;
            border-radius: 50%;
            display: inline-block;
            line-height: 24px;
            color: black;
            font-size: 12px;
            font-weight: bold;
        }

        .step.active .circle {
            background: #28a745;
            color: white;
        }

        .label {
            display: block;
            font-size: 10px;
            margin-top: 4px;
            color: #060606;
        }

        .progress-circle {
            width: 60px;
            height: 60px;
            margin-left: 15px;
        }

        .circular-chart {
            width: 100%;
            height: 100%;
        }

        .circle-bg {
            fill: none;
            stroke: #eee;
            stroke-width: 3.8;
        }

        .circle {
            fill: none;
            stroke: #28a745;
            stroke-width: 3.8;
            stroke-linecap: round;
            transition: stroke-dasharray 0.6s ease;
        }

        .percentage {
            fill: #333;
            font-family: sans-serif;
            font-size: 0.5em;
            text-anchor: middle;
        }

        .step .circle {
            border-radius: 50%;
            width: 30px;
            height: 30px;
            color: white;
            display: inline-flex;
            align-items: center;
            justify-content: center;
        }

        .step.not-required .circle {
            background-color: #bdbdbd;
        }

        .step.active .circle {

            background-color: #5586b1;
            color: white;
        }

        .step.completed .circle {
            background-color: #149514;
        }
    </style>


    <div class="page-heading">
        <!-- You need to delete this fetch once all things are done and working -->
        <!-- 1- Next and back btns working order to the compliance type order, 
          2- Progress Bar working order is typical to compliance type order
          3- Remove all CSS from web templates and pages and put it into quickshifts CSS. -->

        {% fetchxml candregistrationpagesold %}
        <fetch version="1.0" output-format="xml-platform" mapping="logical" distinct="false">
            <entity name="mspp_webpage">
                <attribute name="mspp_webpageid" />
                <attribute name="mspp_name" />
                <attribute name="mspp_title" />
                <attribute name="mspp_partialurl" />
                <attribute name="mspp_pagetemplateid" />
                <attribute name="mspp_displayorder" />
                <order attribute="mspp_displayorder" descending="false" />
                <filter type="and">
                    <condition attribute="mspp_pagetemplateid" operator="eq" uiname="Candidate Registrations"
                        uitype="mspp_pagetemplate" value="{DEB1DF00-E60E-EF11-9F89-002248CBBBD1}" />
                    <condition attribute="mspp_isroot" operator="eq" value="1" />
                </filter>
            </entity>
        </fetch>
        {% endfetchxml %}

        <!-- FROM HERE -->
        {% fetchxml candregistrationpages %}
        <fetch version="1.0" output-format="xml-platform" mapping="logical" distinct="false">
            <entity name="new_complianceform">
                <attribute name="new_complianceformid" />
                <attribute name="new_name" />
                <attribute name="createdon" />
                <attribute name="new_webpageid" />
                <attribute name="new_order" />
                <attribute name="new_compliancetypeid" />
                <order attribute="new_order" descending="false" />
                <filter type="and">
                    <condition attribute="statecode" operator="eq" value="0" />
                    <condition attribute="new_compliancetypeid" operator="eq" uitype="new_compliancetype"
                        value="{{compliancetypeid}}" />
                </filter>
                <link-entity name="mspp_webpage" from="mspp_webpageid" to="new_webpageid" alias="WebPage"
                    link-type="outer">
                    <attribute name="mspp_displayorder" />
                    <attribute name="mspp_title" />
                    <attribute name="mspp_partialurl" />
                </link-entity>
            </entity>
        </fetch>
        {% endfetchxml %}

        <div id="pages-container" style="display: none;" data-pages='[
                {% for page in candregistrationpages.results.entities %}
                {
                    "title": "{{ page["WebPage.mspp_title"] | escape }}",
                    "partialurl": "{{ page["WebPage.mspp_partialurl"] | escape }}"
                }{% unless forloop.last %},{% endunless %}
                {% endfor %}
            ]'>
        </div>

        <script type="text/javascript">

            const regId = "{{registrationid}}";

            function isSessionValid() {
                const sessionExpiry = localStorage.getItem('QSsessionExpiry');
                if (!sessionExpiry) return false;
                return new Date() < new Date(sessionExpiry);
            }

            const raw = document.getElementById('pages-container').getAttribute('data-pages');
            let formSteps = [];

            try {
                formSteps = JSON.parse(raw);
                console.log("formSteps is: ",formSteps);
                
            } catch (e) {
                console.error("Invalid JSON in data-pages:", e, raw);
            }

            function isPageComplete(stepPath) {
                const progressStatus = JSON.parse(localStorage.getItem('QSprogressStatus') || '{}');
                return !!progressStatus[stepPath];
            }

            // Start new function to check table rows
            function hasValidTableRows(currentPath) {
                if (currentPath === 'declarations') {
                    const wasEdited = localStorage.getItem(`declarationEdited_${regId}`) === 'true';
                    return wasEdited; // Only consider valid after user interaction
                }

                let found = false;
                $('table:visible').each(function () {
                    $(this).find('tr:visible').each(function () {
                        const $tds = $(this).find('td').filter(function () {
                            const text = $(this).text().trim().toLowerCase();
                            return text.length > 0 && text !== 'actions';
                        });
                        if ($tds.length > 1) {
                            found = true;
                            return false;
                        }
                    });
                    if (found) return false;
                });
                return found;
            }


            // End function to check table rows

            // Start saveCurrentPageStatus Func

            function saveCurrentPageStatus() {
                const currentPath = window.location.pathname.toLowerCase()
                    .replace(/^\/[a-z]{2}-[a-z]{2}\//, '')
                    .replace(/^\/|\/$/g, '');

                const $requiredFields = $('input[aria-required="true"]:visible, select[aria-required="true"]:visible, textarea[aria-required="true"]:visible');
                let allFilled = true;

                $requiredFields.each(function () {
                    const $field = $(this);
                    const id = $field.attr('id');
                    const val = $field.val();

                    // Skip ghost date picker
                    if (id === 'new_dateofbirth_datepicker_description') return;

                    if (!val || val.trim() === '') {
                        console.warn(`❌ Empty required field: ${id}`);
                        allFilled = false;
                    }
                });

                const hasRequiredFields = $requiredFields.length > 0;
                let completed = hasRequiredFields ? allFilled : hasValidTableRows(currentPath);



                // ✅ Special handling for Declarations step

                if (currentPath === 'declarations') {
                    const wasEdited = localStorage.getItem(`declarationEdited_${regId}`) === 'true';
                    completed = wasEdited;

                    if (wasEdited) {
                        console.log("✅ Declarations step edited — marked complete.");
                    } else {
                        console.warn("❌ Declarations step not edited — still incomplete.");
                    }
                }


                const progressStatus = JSON.parse(localStorage.getItem('QSprogressStatus') || '{}');
                progressStatus[currentPath] = completed;
                localStorage.setItem('QSprogressStatus', JSON.stringify(progressStatus));

                // Update first step flag
                const firstStepPath = formSteps.length ? formSteps[0].partialurl.toLowerCase().replace(/^\/|\/$/g, '') : '';
                const firstStepHasMissingFields = (currentPath === firstStepPath && !completed);
                localStorage.setItem('QSfirstStepIncomplete', JSON.stringify(firstStepHasMissingFields));

                console.log(`🔄 saveCurrentPageStatus: [${currentPath}] = ${completed}`);
            }

            // End saveCurrentPageStatus Func


            function updateProgressBar() {
                const progressStatus = JSON.parse(localStorage.getItem('QSprogressStatus') || '{}');
                const currentPath = window.location.pathname.toLowerCase().replace(/^\/[a-z]{2}-[a-z]{2}\//, '').replace(/^\/|\/$/g, '');
                const currentIndex = formSteps.findIndex(step => step.partialurl.toLowerCase() === currentPath);


                let stepsHtml = '';
                let totalSteps = formSteps.length;
                let completedSteps = 0;

                formSteps.forEach((step, i) => {
                    const stepPath = step.partialurl.toLowerCase();
                    const isCurrent = i === currentIndex;
                    let isComplete = progressStatus[stepPath];

                    if (stepPath === 'declarations' && !localStorage.getItem(`declarationEdited_${regId}`)) {
                        isComplete = false;
                    }

                    let statusClass = '';
                    let stepIcon = (i + 1);

                    if (isComplete) {
                        statusClass = 'completed';
                        stepIcon = '✔';
                        completedSteps++;
                    } else if (isCurrent) {
                        statusClass = 'active';
                        stepIcon = '⏳';
                    }

                    stepsHtml += `<div class="step ${statusClass}">
                        <span class="circle">${stepIcon}</span>
                        <span class="label">${step.title}</span>
                    </div>`;
                });

                let progressPercent = Math.round((completedSteps / totalSteps) * 100);
                if (progressPercent > 100) progressPercent = 100;

                const strokeColor = progressPercent === 100 ? '#28a745' : '#00b8d4';

                const progressBarHtml = `
                    <div class="progress-container">
                        <div class="steps-wrapper">${stepsHtml}</div>
                        <div class="progress-circle">
                            <svg viewBox="0 0 36 36" class="circular-chart">
                                <path class="circle-bg"
                                    d="M18 2.0845
                                       a 15.9155 15.9155 0 0 1 0 31.831
                                       a 15.9155 15.9155 0 0 1 0 -31.831" />
                                <path class="circle" style="stroke: ${strokeColor}; stroke-dasharray: ${progressPercent}, 100"
                                    d="M18 2.0845
                                       a 15.9155 15.9155 0 0 1 0 31.831
                                       a 15.9155 15.9155 0 0 1 0 -31.831" />
                                <text x="18" y="20.35" class="percentage">${progressPercent}%</text>
                            </svg>
                        </div>
                    </div>`;

                $('.progress-container').remove();
                $('.page-copy').prepend(progressBarHtml);
            }


            $(document).ready(function () {

                // Start Validate Declaration

                // ✅ Utility: Normalize path once and reuse
                const currentPath = window.location.pathname.toLowerCase()
                    .replace(/^\/[a-z]{2}-[a-z]{2}\//, '')
                    .replace(/^\/|\/$/g, '');

                const regId = "{{registrationid}}";
                const sessionKey = `QSformSession_${regId}`;

                // ✅ Session initialization (one-time)
                if (!localStorage.getItem(sessionKey)) {
                    console.log(`🧹 New form session detected — clearing declarationEdited_${regId}`);
                    localStorage.removeItem(`declarationEdited_${regId}`);
                    localStorage.setItem(sessionKey, 'true');
                }

                // ✅ Initialize QSprogressStatus only if empty
                if (!localStorage.getItem('QSprogressStatus')) {
                    const initialStatus = Object.fromEntries(
                        formSteps.map(step => [step.partialurl.toLowerCase().replace(/^\/|\/$/g, ''), false])
                    );
                    localStorage.setItem('QSprogressStatus', JSON.stringify(initialStatus));
                }

                // ✅ Track visited pages (declarations excluded until actual interaction)
                if (currentPath !== 'declarations') {
                    const visitedPages = new Set(JSON.parse(localStorage.getItem('QSvisitedSteps') || '[]'));
                    if (!visitedPages.has(currentPath)) {
                        visitedPages.add(currentPath);
                        localStorage.setItem('QSvisitedSteps', JSON.stringify([...visitedPages]));
                    }
                }

                // ✅ Declarations: Single delegated handler for all interactions
                if (currentPath === 'declarations') {
                    $('#candidatedeclarations').on(
                        'input change click',
                        'input, select, textarea, .btn, button',
                        () => {
                            if (!localStorage.getItem(`declarationEdited_${regId}`)) {
                                localStorage.setItem(`declarationEdited_${regId}`, 'true');
                                console.log("✅ Declaration interaction detected — marked as edited.");
                            }

                            // ✅ Mark page as visited after real interaction
                            const visitedPages = new Set(JSON.parse(localStorage.getItem('QSvisitedSteps') || '[]'));
                            if (!visitedPages.has(currentPath)) {
                                visitedPages.add(currentPath);
                                localStorage.setItem('QSvisitedSteps', JSON.stringify([...visitedPages]));
                            }

                            saveCurrentPageStatus();
                            updateProgressBar();
                        }
                    );
                }


                // End Vaildate Declaration

                // Start Filter Right to work
                console.log("⏳ Waiting for 'New right to work' button...");

                // Set initial isUKResident from selected radio button
                var selected = $('input[name*="new_aretheyaukresident"]:checked').val();
                window.isUKResident = selected;
                console.log("Initial isUKResident:", window.isUKResident);

                $('input[id="new_aretheyaukresident_0"], input[id="new_aretheyaukresident_1"]').on('change', function () {
                    const isUKResident = $(this).val(); // "1" for Yes, "0" for No
                    console.log("Selected isUKResident:", isUKResident);
                    window.isUKResident = isUKResident;
                });
                // End Filter Right to work

                // End Disclamir in RTW


                // Start instructions in Personal Details

                const $uploadLabel = $('label[for="personaldetailsuploads"]');

                // Only add the message once
                if ($('#id-ni-message').length === 0 && $uploadLabel.length) {
                    const $message = $('<div id="id-ni-message" style="margin-top: 5px; font-weight: 500; color: black;"><br>Please upload the ID and Proof of National Insurance.</div>');
                    $uploadLabel.after($message);
                }


                // End instructions in Personal Details

                // Start Add Criminal Conviations Link to Declaration
                let linkClicked = false;

                // Create and insert the link
                const labelContainer = document.getElementById("new_readcriminalconvictions_label");
                const link = document.createElement("a");
                const br = document.createElement("br");

                link.href = "/ReadCriminalConvictions";
                link.id = "readLink";
                link.target = "_blank";
                link.textContent = "Read Criminal Convictions";
                link.style.display = "inline-block";
                link.style.marginTop = "5px";
                link.style.marginRight = "60px";
                link.style.color = "#d4000e";

                link.addEventListener("click", function () {
                    linkClicked = true;
                    this.style.color = "#0078D4";
                });

                if (labelContainer) {
                    labelContainer.parentNode.insertBefore(br, labelContainer.nextSibling);
                    labelContainer.parentNode.insertBefore(link, br.nextSibling);
                }

                // Prevent selecting "Yes" unless link was clicked
                const yesRadio = document.getElementById("new_readcriminalconvictions_1");

                if (yesRadio) {
                    yesRadio.addEventListener("click", function (e) {
                        if (!linkClicked) {
                            e.preventDefault();
                            alert("Please read the Criminal Convictions information before selecting 'Yes'.");
                        }
                    });
                }

                // End Add Criminal Conviations Link to Declaration

                // Start Drive Lisence Conditional Field

                function toggleAttachmentRow() {
                    const selectedVal = $('#new_validdrivinglicense input[type="radio"]:checked').val();
                    console.log('Radio value:', selectedVal);

                    const $attachmentContainer = $('.file-control-container');
                    const labelText = $('#new_drivinglicense_label');

                    const $radioGroup = $('#new_validdrivinglicense'); // Container for Yes/No radio buttons

                    // Create or find the instruction message
                    let $instructionMsg = $('#driving-license-msg');
                    if ($instructionMsg.length === 0) {
                        $instructionMsg = $('<div id="driving-license-msg" style="color: #0078d4; font-weight: 500; margin-top: 8px;">Please upload a valid driving license in Uploads Section Below.</div>');
                        $radioGroup.after($instructionMsg); // Insert the message after the Yes/No field
                    }

                    console.log('Attachment Row found:', $attachmentContainer.length);
                    console.log('Label found:', labelText.length);
                    console.log('Label text:', labelText.text());

                    if (selectedVal === "1") { // "Yes"
                        $attachmentContainer.show();
                        labelText.show();
                        $instructionMsg.show();
                    } else {
                        $attachmentContainer.hide();
                        labelText.hide();
                        $instructionMsg.hide();
                    }
                }

                // Run on load after a short delay
                setTimeout(toggleAttachmentRow, 500);

                // Run when radio button value changes
                $('#new_validdrivinglicense input[type="radio"]').on('change', toggleAttachmentRow);

                // End Drive Lisence Conditional Field

                // Create the button element
                const backButton = document.createElement('button');
                backButton.id = 'backButton';
                backButton.type = 'button';
                backButton.className = 'btn btn-secondary';
                backButton.style.marginRight = '10px';
                backButton.textContent = 'Back';

                // Find the container on the right side
                const rightContainer = document.querySelector('.form-action-container-right');

                // Append the button to the right container
                if (rightContainer) {
                    rightContainer.appendChild(backButton);
                }

                const normalizedPath = window.location.pathname
                    .toLowerCase()
                    .replace(/^\/[a-z]{2}-[a-z]{2}\//, '') // Strip locale prefix
                    .replace(/^\/|\/$/g, '');              // Strip leading/trailing slashes

                // Check if there's a previous page on load
                const idx = formSteps.findIndex(step =>
                    step.partialurl.toLowerCase().replace(/^\/|\/$/g, '') === normalizedPath
                );
                if (idx <= 0) {
                    $('#backButton').hide(); // Hide on first page
                }

                const $updateBtn = $('#UpdateButton');
                if (idx >= 0 && idx + 1 < formSteps.length) {
                    $updateBtn.val('Next').attr('title', 'Next');
                } else {
                    $updateBtn.val('Submit').attr('title', 'Submit');
                }

                // Back button logic
                $('#backButton').on('click', function () {
                    if (idx > 0) {
                        const previousStep = formSteps[idx - 1];
                        if (previousStep && previousStep.partialurl) {
                            const queryString = window.location.search; // includes ?registrationid=...&contactid=...
                            const formattedUrl = '/' + previousStep.partialurl.replace(/^\/|\/$/g, '') + '/' + queryString;
                            window.location.href = formattedUrl;
                        }
                    }
                });

                if (!formSteps.length) return;

                setTimeout(() => {
                    const path = window.location.pathname.toLowerCase().replace(/^\/[a-z]{2}-[a-z]{2}\//, '').replace(/^\/|\/$/g, '');
                    if (path !== 'declarations') {
                        saveCurrentPageStatus();
                        updateProgressBar();
                    }
                }, 500);

                // Listen to changes on any required field
                $(document).on('input change blur', 'input[aria-required="true"], select[aria-required="true"], textarea[aria-required="true"]', function () {
                    saveCurrentPageStatus();
                    updateProgressBar();
                });

                // Listen to table changes (for pages with only record tables)
                const observer = new MutationObserver(function () {
                    saveCurrentPageStatus();
                    updateProgressBar();
                });

                //const target = document.querySelector('.entitylist, .record-list');
                // Replased code
                $('table').each(function () {
                    observer.observe(this, { childList: true, subtree: true });
                });

                $('input[required], select[required], textarea[required]').on('input change', function () {
                    saveCurrentPageStatus();
                    updateProgressBar();
                });

                const nextUrl = localStorage.getItem('afterSaveAndNext');
                if (nextUrl) {
                    localStorage.removeItem('afterSaveAndNext');
                    window.location.href = nextUrl;
                    return;
                }
                //  b) afterFinalSubmit → go to compliance-case
                if (localStorage.getItem('afterFinalSubmit') === 'true') {
                    localStorage.removeItem('afterFinalSubmit');
                    const m = window.location.pathname.match(/^\/([a-z]{2}-[A-Z]{2})\//);
                    const locale = m ? m[1] : 'en-US';
                    const qs = window.location.search;
                    window.location.href = `/${locale}/compliancecase/${qs}`;
                    return;
                }

                $('#UpdateButton').on('click', function () {
                    saveCurrentPageStatus();

                    const currentPath = window.location.pathname.toLowerCase().replace(/^\/[a-z]{2}-[a-z]{2}\//, '').replace(/^\/|\/$/g, '');
                    const idx = formSteps.findIndex(step =>
                        step.partialurl.toLowerCase().replace(/^\/|\/$/g, '') === currentPath
                    );

                    if (idx >= 0 && idx + 1 < formSteps.length) {
                        const next = formSteps[idx + 1];
                        const localeMatch = window.location.pathname.match(/^\/([a-z]{2}-[A-Z]{2})\//);
                        const locale = localeMatch ? localeMatch[1] : 'en-US';
                        const qs = window.location.search;
                        const nextPartial = next.partialurl.replace(/^\/|\/$/g, '');
                        const fullNextUrl = `/${locale}/${nextPartial}/${qs}`;

                        // set flag, let the built-in onclick save for us
                        localStorage.setItem('afterSaveAndNext', fullNextUrl);

                        // NO e.preventDefault() — allow WebForm_DoPostBack… to fire
                    } else {
                        // → we're on the final “Submit”
                        localStorage.setItem('afterFinalSubmit', 'true');
                        // NO e.preventDefault() — allow built-in save
                    }
                });

                // Retry check for table rows after delay (dynamic data)
                // Force recheck after delay to handle async table loads
                setTimeout(() => {
                    console.log("Rechecking table state after delay...");
                    saveCurrentPageStatus();
                    updateProgressBar();
                }, 2000);


                setTimeout(() => {
                    console.log("Rechecking Second table state after delay...");
                    saveCurrentPageStatus();
                    updateProgressBar();
                }, 4000);

            });



        </script>

</html>"
}
